namespace GastosApp.BusinessLogic.Models.Investments;

public sealed class InvestmentTierInput { public decimal MinimumAmount { get; set; } public decimal? MaximumAmount { get; set; } public decimal AnnualRatePercent { get; set; } }
public sealed class InvestmentOfferInput { public string CapturedForMonth { get; set; } = string.Empty; public DateOnly ValidFrom { get; set; } public DateOnly ValidTo { get; set; } public string SourceUrl { get; set; } = string.Empty; public string SourceLabel { get; set; } = string.Empty; public bool ConditionsConfirmed { get; set; } public List<InvestmentTierInput> Tiers { get; set; } = []; }
public sealed class InvestmentProductInput { public int AccountId { get; set; } public string Name { get; set; } = string.Empty; public string Institution { get; set; } = string.Empty; public bool Active { get; set; } = true; public List<InvestmentOfferInput> Offers { get; set; } = []; }
public sealed class InvestmentProjectionRow { public int MonthNumber { get; init; } public string Month { get; init; } = string.Empty; public decimal OpeningBalance { get; init; } public decimal Interest { get; init; } public decimal ClosingBalance { get; init; } }
public sealed class InvestmentPlanResult { public int InvestmentPlanId { get; init; } public string PlanMonth { get; init; } = string.Empty; public int ProjectionMonths { get; init; } public List<InvestmentAllocationResult> Allocations { get; init; } = []; }
public sealed class InvestmentAllocationResult { public int InvestmentProductId { get; init; } public int AccountId { get; init; } public string ProductName { get; init; } = string.Empty; public string Institution { get; init; } = string.Empty; public decimal CurrentAccountBalance { get; init; } public decimal AllocatedAmount { get; init; } public string? IneligibleReason { get; init; } public List<InvestmentProjectionRow> Projection { get; init; } = []; }
